                // $0b5d6  beq.w $1b5e0
                {
                    k.cy +%= 14;
                    if (k.fz) continue :sw 0x1b5e0;
                }
                // $0b5da  bgt.w $1b5f0
                {
                    k.cy +%= 14;
                    if (!k.fz and k.fneg == k.fv) continue :sw 0x1b5f0;
                }
                // $0b5de  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            0x1b5e0 => {
                // $0b5e0  adda.l #$6, a0
                {
                    k.cy +%= 12;
                    k.a[0] +%= @as(u32, 0x6);
                }
                // $0b5e6  adda.l #$2, a3
                {
                    k.cy +%= 12;
                    k.a[3] +%= @as(u32, 0x2);
                }
                // $0b5ec  dbra d1, $1b5d0
                {
                    k.cy +%= 14;
                    const w = k.dv(u16, 1) -% 1;
                    k.setD(u16, 1, w);
                    if (w != 0xFFFF) { if (k.cy >= k.limit) return 0x1b5d0; continue :sw 0x1b5d0; }
                }
                continue :sw 0x1b5f0;
            },
            0x1b5f0 => {
                // $0b5f0  addi.b #$1, (a2)
                {
                    k.cy +%= 12;
                    const s = @as(u8, 0x1);
                    const e1: u32 = k.a[2];
                    const r = k.add(u8, s, k.rb(e1));
                    k.wb(e1, r);
                }
                // $0b5f4  addi.l #$10, (a1)
                {
                    k.cy +%= 20;
                    const s = @as(u32, 0x10);
                    const e1: u32 = k.a[1];
                    const r = k.add(u32, s, k.rl(e1));
                    k.wl(e1, r);
                }
                // $0b5fa  move.b #$6, $1ac10.l
                {
                    k.cy +%= 20;
                    const v = @as(u8, 0x6);
                    const e1: u32 = 0x1ac10;
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $0b602  jsr $1ac12.l
                {
                    k.cy +%= 36;
                    k.push32(0x1b608);
                    return 0x1ac12;
                }
            },
            0x1b608 => {
                // $0b608  jsr $11c46.l
                {
                    k.cy +%= 36;
                    k.push32(0x1b60e);
                    return 0x11c46;
                }
            },
            0x1b60e => {
                // $0b60e  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

